import{_ as n,C as o,o as s,c as p,a2 as a,b as d,w as i,a as h,E as l,a3 as r}from"./chunks/framework.iE4fH2S6.js";const v=JSON.parse('{"title":"Deploying the server","description":"","frontmatter":{},"headers":[],"relativePath":"docs/deploying-the-server.md","filePath":"docs/deploying-the-server.md"}'),c={name:"docs/deploying-the-server.md"};function k(g,e,y,u,F,m){const t=o("Mermaid");return s(),p("div",null,[e[1]||(e[1]=a('<h1 id="deploying-the-server" tabindex="-1">Deploying the server <a class="header-anchor" href="#deploying-the-server" aria-label="Permalink to &quot;Deploying the server&quot;">​</a></h1><p>The server runs on one Linux machine as Docker containers, behind a shared Caddy for HTTPS. Health data must stay in the EU or Switzerland under the GDPR, so pick a host there (<a href="./architecture#accounts-and-security">architecture</a>). The server currently answers <code>/health</code> with its version; Postgres stays empty until accounts arrive (<a href="https://github.com/tkint/coach-poulpy/issues/25" target="_blank" rel="noreferrer">#25</a>).</p><p>The setup follows <a href="./adr/0019-the-server-runs-with-docker-compose-on-one-server">ADR 0019</a>. Deployment files are in <a href="https://github.com/tkint/coach-poulpy/tree/main/deploy" target="_blank" rel="noreferrer"><code>deploy/</code></a>, and each <a href="./releasing#the-server">release</a> includes a deployment bundle.</p><h2 id="the-containers" tabindex="-1">The containers <a class="header-anchor" href="#the-containers" aria-label="Permalink to &quot;The containers&quot;">​</a></h2>',4)),(s(),d(r,null,{default:i(()=>[l(t,{id:"mermaid-12",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20internet((%22Internet%22))%20--%20%2280%20and%20443%22%20--%3E%20caddy%0A%20%20%20%20subgraph%20edgeproj%5B%22edge%20project%22%5D%0A%20%20%20%20%20%20%20%20caddy%5B%22caddy%20%C2%B7%20shared%20HTTPS%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20appproj%5B%22coach-poulpy%20project%22%5D%0A%20%20%20%20%20%20%20%20server%5B%22server%20%C2%B7%20coach-poulpy-server%3A8080%22%5D%0A%20%20%20%20%20%20%20%20postgres%5B(%22postgres%20%C2%B7%20postgres-data%22)%5D%0A%20%20%20%20end%0A%20%20%20%20caddy%20--%20%22edge%20network%22%20--%3E%20server%0A%20%20%20%20server%20--%20%22internal%20network%22%20--%3E%20postgres%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a(`<p>Only Caddy publishes ports. The server joins the external <code>edge</code> network using a unique alias and the private <code>internal</code> network; Postgres joins only <code>internal</code>. The app and edge are separate Compose projects, so stopping the app leaves Caddy running. The shared network is for trusted applications: containers on it can reach each other&#39;s app ports.</p><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><ul><li>Linux with Python 3, Docker Engine and Docker Compose 2.24.4 or newer.</li><li>About 1 GB of free memory; the server is capped at 512 MB. Images are built in CI, not on the machine.</li><li>An API hostname whose DNS A/AAAA records point to the machine.</li><li>SSH and ports 80/443 open (TCP, plus UDP 443 for HTTP/3).</li></ul><h2 id="_1-prepare-the-app-settings" tabindex="-1">1. Prepare the app settings <a class="header-anchor" href="#_1-prepare-the-app-settings" aria-label="Permalink to &quot;1. Prepare the app settings&quot;">​</a></h2><p>Unpack a deployment bundle containing <code>edge/deploy.py</code> from the <a href="https://github.com/tkint/coach-poulpy/releases" target="_blank" rel="noreferrer">Releases</a> page. Replace <code>vX.Y.Z</code> with that release&#39;s tag:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/coach-poulpy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/coach-poulpy</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/tkint/coach-poulpy/releases/download/vX.Y.Z/coach-poulpy-deploy.tar.gz</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --strip-components=1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 600</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span></code></pre></div><p>Set <code>DOMAIN</code> to the API hostname without a scheme, port or path. Set <code>POSTGRES_PASSWORD</code>, for example to the output of <code>openssl rand -hex 24</code>. Keep <code>.env</code> and the existing app directory/project name on subsequent deployments.</p><p>If <code>ghcr.io/tkint/coach-poulpy-server</code> is private, log in once with a token that can read packages: <code>docker login ghcr.io</code>.</p><h2 id="_2-deploy" tabindex="-1">2. Deploy <a class="header-anchor" href="#_2-deploy" aria-label="Permalink to &quot;2. Deploy&quot;">​</a></h2><p>From the unpacked bundle:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> edge/deploy.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --app-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --compose-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose.yaml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --site-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> coach-poulpy.caddy</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://api.example.com/health</span></span></code></pre></div><p>From a repository checkout, the equivalent is:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/edge/deploy.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --app-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/coach-poulpy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --compose-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/compose.yaml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --site-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/coach-poulpy.caddy</span></span></code></pre></div><p>The deployer creates the external network if needed, renders this app&#39;s <code>DOMAIN</code> into its site file, validates the combined Caddy configuration, pulls the images and starts or updates both projects. It handles an absent, running or stopped shared Caddy, with or without the app already deployed.</p><p>The shared Caddy lives in <code>~/edge</code> by default; <code>--edge-dir</code> changes that location. Every deployment sharing Caddy must use the same directory, Compose project and network. <code>EDGE_NETWORK</code> defaults to <code>edge</code>; custom values must match the edge&#39;s network. Do not combine the edge and app Compose files into one project.</p><p>Existing site files and a customized edge <code>Caddyfile</code> are preserved. Deployment updates only <code>sites/coach-poulpy.caddy</code>, starts Caddy if necessary and reloads the generated configuration. A host-level lock serializes independent deployments, preventing concurrent site updates from being lost.</p><p>Caddy runs <code>generated/caddy.json</code>, built from the root Caddyfile, all site files and any migrated legacy routes. Do not edit generated JSON by hand; change <code>.env</code> or the source site template and redeploy. HTTPS errors are usually caused by DNS or blocked ports; inspect <code>cd ~/edge &amp;&amp; docker compose logs caddy</code>.</p><h2 id="existing-app-owned-caddy" tabindex="-1">Existing app-owned Caddy <a class="header-anchor" href="#existing-app-owned-caddy" aria-label="Permalink to &quot;Existing app-owned Caddy&quot;">​</a></h2><p>The same deployment automatically migrates a standard Docker Caddy owning host ports 80/443, including a stopped container. Back up application data and configuration first.</p><p>Migration adapts the existing <code>/etc/caddy/Caddyfile</code> using its original environment, preserves other sites, reuses named <code>/data</code> and <code>/config</code> volumes and retains the networks needed by existing upstreams. Docker aliases are resolved to unique container names so a new service cannot shadow an old upstream.</p><p>Only the hostname being redeployed replaces its legacy route. Other legacy routes remain until their owners redeploy, and legacy networks are detached once no legacy proxy routes remain. Keep <code>legacy.json</code>, <code>migration.compose.json</code> and the original certificate volumes: they are active deployment state.</p><p>The swap briefly interrupts HTTPS. Configuration is validated before stopping the old Caddy. If the new edge cannot start, the deployer restores saved edge files and restarts the original Caddy. An application update may already have completed; deployment reports that explicitly rather than claiming a full application rollback.</p><p>Ambiguous port owners, non-Caddy containers, custom legacy mounts/config paths and conflicting Caddy settings fail explicitly without stopping the existing proxy. A host-installed Caddy needs explicit manual migration. Never use <code>docker compose down -v</code> to clean up a migrated stack.</p><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h2><p>Run <strong>Actions &gt; Deploy &gt; Run workflow</strong> with <code>latest</code> or a version. The workflow uploads deployment files from its checked-out ref and selects the app image using the version input. It runs the same deployer, so it also updates this app&#39;s Caddy site and starts Caddy if absent or stopped. SSH settings: <a href="./releasing#deploy-the-server">Releasing</a>.</p><p>For manual updates, unpack the new bundle in a staging directory and point it at the existing app:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> edge/deploy.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --app-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/coach-poulpy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --compose-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose.yaml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --site-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> coach-poulpy.caddy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> latest</span></span></code></pre></div><p>Omit <code>--version</code> to use <code>IMAGE_TAG</code> from <code>.env</code>. Neither deployment path overwrites <code>.env</code> or another app&#39;s site. Use <code>--no-pull</code> only with locally built or preloaded images.</p><p>For direct edge inspection after migration, include its override:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/edge</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose.yaml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migration.compose.json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span></span></code></pre></div><p>Omit <code>-f migration.compose.json</code> if no migration took place. Also include <code>-f compose.override.yaml</code> if the edge is customized; deployment includes both automatically.</p><h2 id="backups" tabindex="-1">Backups <a class="header-anchor" href="#backups" aria-label="Permalink to &quot;Backups&quot;">​</a></h2><p>Postgres has nothing to back up until accounts arrive. After that, dump it nightly and store the dumps off-machine in the EU or Switzerland:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/backups</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/coach-poulpy</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -T</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pg_dump</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -U</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> coachpoulpy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Fc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> coachpoulpy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/backups/coachpoulpy-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">date</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +%F</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.dump</span></span></code></pre></div><p>Restore with <code>pg_restore -U coachpoulpy -d coachpoulpy --clean</code>, fed through <code>docker compose exec -T postgres</code>. Back up <code>.env</code> and the shared edge&#39;s configuration and migration state as well. Losing Caddy&#39;s certificate volume requires issuing new certificates.</p>`,35))])}const f=n(c,[["render",k]]);export{v as __pageData,f as default};
